<?php

namespace App\Services;

use App\Enums\ImageViewType;
use App\Jobs\ExtractSpinSet;
use App\Jobs\ProcessProductImage;
use App\Models\Product;
use App\Models\ProductImage;
use Illuminate\Http\UploadedFile;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Storage;
use Illuminate\Support\Str;

/**
 * Stores gallery uploads under SEO-friendly names and queues their processing.
 * Originals are kept untouched; renditions are generated by ProcessProductImage.
 */
class ProductImageService
{
    /** @param array{alt?: ?string, view_type?: string, is_lifestyle?: bool} $attributes */
    public function store(Product $product, UploadedFile $file, array $attributes = []): ProductImage
    {
        $viewType = ImageViewType::tryFrom($attributes['view_type'] ?? '') ?? ImageViewType::Other;
        $next = (int) $product->images()->max('sort_order') + 1;
        $isFirstPhoto = empty($attributes['is_lifestyle']) && $product->galleryImages()->doesntExist();

        $name = $this->fileName($product, $viewType, $next).'.'.strtolower($file->extension() ?: 'jpg');
        $image = $product->images()->create([
            'path' => $file->storeAs("products/{$product->id}/originals", $name, 'public'),
            'alt' => $attributes['alt'] ?? null,
            'view_type' => $viewType,
            'is_lifestyle' => (bool) ($attributes['is_lifestyle'] ?? false),
            'is_primary' => $isFirstPhoto,
            'sort_order' => $next,
        ]);

        ProcessProductImage::dispatch($image);

        return $image;
    }

    /**
     * {brand}-{model}-{color}-{view_type}-{n}, e.g. refra-atelier-ra-mt7-amber-tortoise-front-3.
     * A short random suffix keeps re-uploads from overwriting cached files.
     */
    public function fileName(Product $product, ImageViewType $viewType, int $n): string
    {
        $parts = [$product->brand, $product->model_no ?: $product->name, $product->color_name ?: $product->color, $viewType->value, $n];

        return Str::limit(Str::slug(implode(' ', array_filter($parts, fn ($p) => $p !== null && $p !== ''))), 90, '').'-'.Str::lower(Str::random(5));
    }

    /** @param list<int> $ids image ids in their new order */
    public function reorder(Product $product, array $ids): void
    {
        DB::transaction(function () use ($product, $ids) {
            foreach (array_values($ids) as $position => $id) {
                $product->images()->whereKey($id)->update(['sort_order' => $position]);
            }
        });
    }

    /** Only one primary photo per product. */
    public function makePrimary(ProductImage $image): void
    {
        DB::transaction(function () use ($image) {
            ProductImage::query()->where('product_id', $image->product_id)->whereKeyNot($image->id)->update(['is_primary' => false]);
            $image->forceFill(['is_primary' => true, 'is_lifestyle' => false])->save();
        });
    }

    /** Store an uploaded ZIP of turntable frames and queue its extraction into a spin set. */
    public function storeSpinArchive(Product $product, UploadedFile $zip): string
    {
        $path = $zip->storeAs('spin-uploads', "product-{$product->id}-".Str::lower(Str::random(8)).'.zip', 'local');
        ExtractSpinSet::dispatch($product, $path);

        return $path;
    }

    /** Store an uploaded 3D model (.glb) for the 360° view, replacing any previous one. */
    public function storeModel(Product $product, UploadedFile $file): void
    {
        // A unique name per upload, so browsers and CDNs can cache it forever.
        $name = Str::slug($product->slug).'-'.Str::lower(Str::random(8)).'.glb';
        $path = $file->storeAs("products/{$product->id}/model", $name, 'public');

        $previous = $product->model_3d_path;
        $product->forceFill(['model_3d_path' => $path])->save();
        if ($previous) {
            Storage::disk('public')->delete($previous);
        }
    }

    public function removeModel(Product $product): void
    {
        if ($product->model_3d_path) {
            Storage::disk('public')->delete($product->model_3d_path);
            $product->forceFill(['model_3d_path' => null])->save();
        }
    }
}
